Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
hwmon: (macsmc) Fix regressions in Apple Silicon SMC hwmon
 driver

The recently added macsmc-hwmon driver contained several critical
bugs in its sensor population logic and float conversion routines.

Specifically:
- The voltage sensor population loop used the wrong prefix ("volt-"
  instead of "voltage-") and incorrectly assigned sensors to the
  temperature sensor array (hwmon->temp.sensors) instead of the
  voltage sensor array (hwmon->volt.sensors). This would lead to
  out-of-bounds memory access or data corruption when both temperature
  and voltage sensors were present.
- The float conversion in macsmc_hwmon_write_f32() had flawed exponent
  logic for values >= 2^24 and lacked masking for the mantissa, which
  could lead to incorrect values being written to the SMC.

Fix these issues to ensure correct sensor registration and reliable
manual fan control.

Confirm that the reported overflow in FIELD_PREP is fixed by declaring
macsmc_hwmon_write_f32() as __always_inline for a compile test.

Fixes: 785205fd8139 ("hwmon: Add Apple Silicon SMC hwmon driver")
Reported-by: Nathan Chancellor <nathan@kernel.org>
Closes: https://lore.kernel.org/linux-hwmon/20260119195817.GA1035354@ax162/
Cc: James Calligeros <jcalligeros99@gmail.com>
Cc: Nathan Chancellor <nathan@kernel.org>
Cc: Neal Gompa <neal@gompa.dev>
Cc: Janne Grunau <j@jannau.net>
Signed-off-by: Guenter Roeck <linux@roeck-us.net>
Tested-by: Nathan Chancellor <nathan@kernel.org> # build only
Link: https://lore.kernel.org/r/20260129175112.3751907-2-linux@roeck-us.net
Reviewed-by: James Calligeros <jcalligeros99@gmail.com>
Signed-off-by: Guenter Roeck <linux@roeck-us.net>

Here is the root cause:
(1) In sensor population, the voltage sensor loop used the wrong child node prefix "volt-" (instead of "voltage-") and incorrectly assigned sensors to the temperature sensor array (`hwmon->temp.sensors`) instead of the voltage sensor array (`hwmon->volt.sensors`), causing out-of-bounds memory access and data corruption. (2) The float conversion in `macsmc_hwmon_write_f32()` had flawed exponent logic for values ≥ 2^24 (insufficient shifting) and lacked masking of the mantissa (`val & FLT_MANT_MASK`) when constructing the 23-bit mantissa field, leading to incorrect values being written to the SMC and a compile-time overflow in `FIELD_PREP`.

Here is the patch:

 static int macsmc_hwmon_write_f32(struct apple_smc *smc, smc_key key, int value)
 {
 	u64 val;
 	u32 fval = 0;
-	int exp = 0, neg;
+	int exp, neg;

+	neg = value < 0;
 	val = abs(value);
-	neg = val != value;

 	if (val) {
-		int msb = __fls(val) - exp;
-
-		if (msb > 23) {
-			val >>= msb - FLT_MANT_BIAS;
-			exp -= msb - FLT_MANT_BIAS;
-		} else if (msb < 23) {
-			val <<= FLT_MANT_BIAS - msb;
-			exp += msb;
-		}
+		exp = __fls(val);
+
+		if (exp > 23)
+			val >>= exp - 23;
+		else
+			val <<= 23 - exp;

 		fval = FIELD_PREP(FLT_SIGN_MASK, neg) |
 		       FIELD_PREP(FLT_EXP_MASK, exp + FLT_EXP_BIAS) |
-		       FIELD_PREP(FLT_MANT_MASK, val);
+		       FIELD_PREP(FLT_MANT_MASK, val & FLT_MANT_MASK);
 	}

 	return apple_smc_write_u32(smc, key, fval);
 }


 static int macsmc_hwmon_populate_sensors(struct macsmc_hwmon *hwmon,
 					 struct device_node *hwmon_node)
 {
 	struct device_node *key_node __maybe_unused;
 	struct macsmc_hwmon_sensor *sensor;
 	u32 n_current = 0, n_fan = 0, n_power = 0, n_temperature = 0, n_voltage = 0;

 	for_each_child_of_node_with_prefix(hwmon_node, key_node, "current-") {
 		n_current++;
 	}

 	if (n_current) {
 		hwmon->curr.sensors = devm_kcalloc(hwmon->dev, n_current,
 						   sizeof(struct macsmc_hwmon_sensor), GFP_KERNEL);
 		if (!hwmon->curr.sensors)
 			return -ENOMEM;

 		for_each_child_of_node_with_prefix(hwmon_node, key_node, "current-") {
 			sensor = &hwmon->curr.sensors[hwmon->curr.count];
 			if (!macsmc_hwmon_create_sensor(hwmon->dev, hwmon->smc, key_node, sensor)) {
 				sensor->attrs = HWMON_C_INPUT;

 				if (*sensor->label)
 					sensor->attrs |= HWMON_C_LABEL;

 				hwmon->curr.count++;
 			}
 		}
 	}

 	for_each_child_of_node_with_prefix(hwmon_node, key_node, "fan-") {
 		n_fan++;
 	}

 	if (n_fan) {
 		hwmon->fan.fans = devm_kcalloc(hwmon->dev, n_fan,
 					       sizeof(struct macsmc_hwmon_fan), GFP_KERNEL);
 		if (!hwmon->fan.fans)
 			return -ENOMEM;

 		for_each_child_of_node_with_prefix(hwmon_node, key_node, "fan-") {
 			if (!macsmc_hwmon_create_fan(hwmon->dev, hwmon->smc, key_node,
 						     &hwmon->fan.fans[hwmon->fan.count]))
 				hwmon->fan.count++;
 		}
 	}

 	for_each_child_of_node_with_prefix(hwmon_node, key_node, "power-") {
 		n_power++;
 	}

 	if (n_power) {
 		hwmon->power.sensors = devm_kcalloc(hwmon->dev, n_power,
 						    sizeof(struct macsmc_hwmon_sensor), GFP_KERNEL);
 		if (!hwmon->power.sensors)
 			return -ENOMEM;

 		for_each_child_of_node_with_prefix(hwmon_node, key_node, "power-") {
 			sensor = &hwmon->power.sensors[hwmon->power.count];
 			if (!macsmc_hwmon_create_sensor(hwmon->dev, hwmon->smc, key_node, sensor)) {
 				sensor->attrs = HWMON_P_INPUT;

 				if (*sensor->label)
 					sensor->attrs |= HWMON_P_LABEL;

 				hwmon->power.count++;
 			}
 		}
 	}

 	for_each_child_of_node_with_prefix(hwmon_node, key_node, "temperature-") {
 		n_temperature++;
 	}

 	if (n_temperature) {
 		hwmon->temp.sensors = devm_kcalloc(hwmon->dev, n_temperature,
 						   sizeof(struct macsmc_hwmon_sensor), GFP_KERNEL);
 		if (!hwmon->temp.sensors)
 			return -ENOMEM;

 		for_each_child_of_node_with_prefix(hwmon_node, key_node, "temperature-") {
 			sensor = &hwmon->temp.sensors[hwmon->temp.count];
 			if (!macsmc_hwmon_create_sensor(hwmon->dev, hwmon->smc, key_node, sensor)) {
 				sensor->attrs = HWMON_T_INPUT;

 				if (*sensor->label)
 					sensor->attrs |= HWMON_T_LABEL;

 				hwmon->temp.count++;
 			}
 		}
 	}

 	for_each_child_of_node_with_prefix(hwmon_node, key_node, "voltage-") {
 		n_voltage++;
 	}

 	if (n_voltage) {
 		hwmon->volt.sensors = devm_kcalloc(hwmon->dev, n_voltage,
 						   sizeof(struct macsmc_hwmon_sensor), GFP_KERNEL);
 		if (!hwmon->volt.sensors)
 			return -ENOMEM;

-		for_each_child_of_node_with_prefix(hwmon_node, key_node, "volt-") {
-			sensor = &hwmon->temp.sensors[hwmon->temp.count];
+		for_each_child_of_node_with_prefix(hwmon_node, key_node, "voltage-") {
+			sensor = &hwmon->volt.sensors[hwmon->volt.count];
 			if (!macsmc_hwmon_create_sensor(hwmon->dev, hwmon->smc, key_node, sensor)) {
 				sensor->attrs = HWMON_I_INPUT;

 				if (*sensor->label)
 					sensor->attrs |= HWMON_I_LABEL;

 				hwmon->volt.count++;
 			}
 		}
 	}

 	return 0;
 }



